assertions_source:
// Great Lakes Instruments directory integrity; employee fields are global.
people attribute "uid" present;
people attribute "cn" present;
people attribute "mail" present;
people attribute "title" present;
group "HQCustomerSupport" members >= 1;
people in "HQCustomerSupport" attribute "ou" == "Customer Support";
people in "HQCustomerSupport" exactly_one ["HQCustomerSupport","HQEngineering","HQFinance","HQShipping","HQReceiving","ShenzhenEngineering","TijuanaAssembly","TijuanaTest"];
group "HQEngineering" members >= 1;
people in "HQEngineering" attribute "ou" == "Engineering";
people in "HQEngineering" exactly_one ["HQCustomerSupport","HQEngineering","HQFinance","HQShipping","HQReceiving","ShenzhenEngineering","TijuanaAssembly","TijuanaTest"];
group "HQFinance" members >= 1;
people in "HQFinance" attribute "ou" == "Finance";
people in "HQFinance" exactly_one ["HQCustomerSupport","HQEngineering","HQFinance","HQShipping","HQReceiving","ShenzhenEngineering","TijuanaAssembly","TijuanaTest"];
group "HQShipping" members >= 1;
people in "HQShipping" attribute "ou" == "Shipping";
people in "HQShipping" exactly_one ["HQCustomerSupport","HQEngineering","HQFinance","HQShipping","HQReceiving","ShenzhenEngineering","TijuanaAssembly","TijuanaTest"];
group "HQReceiving" members >= 1;
people in "HQReceiving" attribute "ou" == "Receiving";
people in "HQReceiving" exactly_one ["HQCustomerSupport","HQEngineering","HQFinance","HQShipping","HQReceiving","ShenzhenEngineering","TijuanaAssembly","TijuanaTest"];
group "ShenzhenEngineering" members >= 1;
people in "ShenzhenEngineering" attribute "ou" == "Shenzhen Engineering";
people in "ShenzhenEngineering" exactly_one ["HQCustomerSupport","HQEngineering","HQFinance","HQShipping","HQReceiving","ShenzhenEngineering","TijuanaAssembly","TijuanaTest"];
group "TijuanaAssembly" members >= 1;
people in "TijuanaAssembly" attribute "ou" == "Assembly";
people in "TijuanaAssembly" exactly_one ["HQCustomerSupport","HQEngineering","HQFinance","HQShipping","HQReceiving","ShenzhenEngineering","TijuanaAssembly","TijuanaTest"];
group "TijuanaTest" members >= 1;
people in "TijuanaTest" attribute "ou" == "Test and Quality";
people in "TijuanaTest" exactly_one ["HQCustomerSupport","HQEngineering","HQFinance","HQShipping","HQReceiving","ShenzhenEngineering","TijuanaAssembly","TijuanaTest"];
